      return '<section class="project-stage project-results-summary" data-project-results="'+esc(p.id)+'">'+header('成果汇总','作品预览、生成结果与交付文稿。',button('继续制作 →','project-tab',continueTab,'button-secondary'))+(hasResults?showcase+'<p class="project-results-count">'+media.length+' 份图片 / 视频 · '+docs.length+' 份文字交付 · '+completed.length+' 项完成记录</p>'+mediaList+section('文字交付',docs,'document')+taskList:'<p class="project-results-empty">还没有已完成的任务或交付。开始制作后，成果会自动汇集到这里。</p>')+'</section>';
